function formatNumber(value) {
    return Math.floor(value).toLocaleString();
}

function clamp(value, min, max) {
    return Math.min(max, Math.max(min, value));
}

function getDictionaryWordCount() {
    let total = 0;
    wordsByLength.forEach((wordSet) => {
        total += wordSet.size;
    });
    return total;
}

function getDisplayWord(word, maxLength = 10) {
    const cleanWord = String(word);
    if (cleanWord.length <= maxLength) {
        return cleanWord;
    }
    return `${cleanWord.slice(0, maxLength - 1)}…`;
}

function getMonkeyType(typeId) {
    return MONKEY_TYPES.find((type) => type.id === typeId) || MONKEY_TYPES[0];
}

function getRandomFromList(items) {
    return items[Math.floor(Math.random() * items.length)];
}

function getCurrentOffice() {
    return OFFICE_BUILDINGS[clamp(officeLevel, 1, OFFICE_BUILDINGS.length) - 1];
}

function getNextOffice() {
    return OFFICE_BUILDINGS[officeLevel] || null;
}

function getUpgradeLevel(upgradeId) {
    return Number(upgrades[upgradeId]) || 0;
}

function getUpgradeCost(upgradeId) {
    const upgrade = UPGRADE_DEFS[upgradeId];
    const level = getUpgradeLevel(upgradeId);
    return Math.floor(upgrade.baseCost * Math.pow(upgrade.costMultiplier, level));
}

function getSuperRareChance() {
    const office = getCurrentOffice();
    const recruiterBonus = getUpgradeLevel('rareRecruiter') * 0.01;
    return clamp(baseSuperRareChance + recruiterBonus + office.rareBonus, 0.1, 0.25);
}

function getGlobalSpeedMultiplier() {
    const office = getCurrentOffice();
    const upgradeBonus = getUpgradeLevel('fasterTypewriters') * 0.08;
    return 1 + office.speedBonus + upgradeBonus;
}

function getWordIncomeMultiplier() {
    const office = getCurrentOffice();
    const payrollBonus = getUpgradeLevel('bananaPayroll') * 0.12;
    return office.incomeMultiplier * (1 + payrollBonus);
}

function getFlatWordBonus() {
    const office = getCurrentOffice();
    return office.wordBonus + getUpgradeLevel('betterDictionary');
}

function calculateWordPoints(word) {
    const basePoints = word.length + getFlatWordBonus();
    return Math.max(1, Math.floor(basePoints * getWordIncomeMultiplier()));
}

function getTotalSuperRaresOwned() {
    return monkeyRoster.reduce((total, typeId) => {
        return total + (getMonkeyType(typeId).rarity === 'super-rare' ? 1 : 0);
    }, 0);
}

function getUnusedTypeIds(poolIds) {
    const usedTypeIds = new Set(monkeyRoster.filter((typeId) => poolIds.includes(typeId)));
    const unused = poolIds.filter((typeId) => !usedTypeIds.has(typeId));
    return unused.length > 0 ? unused : poolIds;
}

function getRandomMonkeyTypeId() {
    const isSuperRareRoll = Math.random() < getSuperRareChance();
    const sourcePool = isSuperRareRoll ? superRareMonkeyTypeIds : normalMonkeyTypeIds;
    return getRandomFromList(getUnusedTypeIds(sourcePool));
}

function normalizeRosterEntry(entry) {
    if (typeof entry === 'string') {
        return MONKEY_TYPES.some((type) => type.id === entry) ? entry : getRandomFromList(normalMonkeyTypeIds);
    }

    if (entry && typeof entry === 'object' && typeof entry.typeId === 'string') {
        return MONKEY_TYPES.some((type) => type.id === entry.typeId) ? entry.typeId : getRandomFromList(normalMonkeyTypeIds);
    }

    return getRandomFromList(normalMonkeyTypeIds);
}

function getMonkeyRarityLabel(monkeyType) {
    return monkeyType.rarity === 'super-rare' ? 'Super Rare' : 'Normal';
}

function getMonkeySpriteSrc(monkeyType) {
    return MONKEY_SPRITE_DATA[monkeyType.sprite] || monkeyType.sprite;
}

function ensureMonkeyRosterMatchesCount() {
    if (!Array.isArray(monkeyRoster)) {
        monkeyRoster = [];
    }

    monkeyRoster = monkeyRoster.map(normalizeRosterEntry);

    while (monkeyRoster.length < monkeysOwned) {
        monkeyRoster.push(getRandomMonkeyTypeId());
    }

    if (monkeyRoster.length > monkeysOwned) {
        monkeyRoster = monkeyRoster.slice(0, monkeysOwned);
    }
}

function ensureProgressionState() {
    officeLevel = clamp(Number(officeLevel) || 1, 1, OFFICE_BUILDINGS.length);

    Object.keys(UPGRADE_DEFS).forEach((upgradeId) => {
        const level = Number(upgrades[upgradeId]) || 0;
        upgrades[upgradeId] = clamp(level, 0, UPGRADE_DEFS[upgradeId].maxLevel);
    });

    if (!Array.isArray(claimedMilestones)) {
        claimedMilestones = [];
    }
}

function syncOfficeVisuals(force = false) {
    const renderedMonkeyCount = monkeyOfficeGrid.querySelectorAll('[data-monkey-slot]').length;
    const hasEmptyState = Boolean(monkeyOfficeGrid.querySelector('.office-empty-state'));

    if (force || renderedMonkeyCount !== monkeysOwned || (monkeysOwned === 0 && !hasEmptyState)) {
        renderMonkeyOffice();
        return;
    }

    monkeyOfficeSummary.textContent = monkeysOwned === 0
        ? 'No monkeys hired yet.'
        : `${formatNumber(monkeysOwned)} monkey${monkeysOwned === 1 ? '' : 's'} in the office`;
}

function updateDisplay() {
    const currentOffice = getCurrentOffice();

    bananasEl.textContent = formatNumber(bananas);
    lettersEl.textContent = formatNumber(lettersTyped);
    wordsEl.textContent = formatNumber(wordsTyped);
    monkeysEl.textContent = formatNumber(monkeysOwned);
    monkeyCostEl.textContent = formatNumber(monkeyCost);
    monkeyCostInlineEl.textContent = formatNumber(monkeyCost);

    officeLevelLabel.textContent = `Floor ${currentOffice.floor}`;
    officeNameTitle.textContent = currentOffice.name;

    buyMonkeyButton.disabled = bananas < monkeyCost;
    buyMonkeyButton.classList.toggle('can-afford', bananas >= monkeyCost);

    if (recentWords.length === 0) {
        recentWordsList.innerHTML = '<span class="empty-state">No words yet.</span>';
    } else {
        recentWordsList.innerHTML = recentWords
            .map((entry) => `<span class="recent-word">${getDisplayWord(entry.word)} <strong>+${entry.points}</strong></span>`)
            .join('');
    }

    syncOfficeVisuals();
    updateProgressionPanel();
    dictionaryStatus.textContent = `${formatNumber(getDictionaryWordCount())} words loaded`;
}

function clearPlaceholder() {
    if (outputArea.querySelector('.placeholder')) {
        outputArea.innerHTML = '';
    }
}

function appendOutputLetter(letter, source = 'player') {
    clearPlaceholder();

    const charSpan = document.createElement('span');
    charSpan.className = source === 'monkey' ? 'typed-char monkey-char' : 'typed-char';
    charSpan.textContent = letter;
    outputArea.appendChild(charSpan);

    trimOutputArea();
}

function appendWordReward(word, points) {
    const wordSpan = document.createElement('span');
    wordSpan.className = 'word-found';
    wordSpan.textContent = ` ${getDisplayWord(word).toUpperCase()} +${points} 🍌 `;
    outputArea.appendChild(wordSpan);

    trimOutputArea();
}

function trimOutputArea() {
    while (outputArea.childNodes.length > maxOutputNodes) {
        outputArea.removeChild(outputArea.firstChild);
    }

    outputArea.scrollTop = outputArea.scrollHeight;
}

function findNewWordsAtEnd() {
    const foundWords = [];
    const longestPossibleWord = Math.min(maxWordLength, typedStream.length);

    for (let length = minWordLength; length <= longestPossibleWord; length++) {
        const wordSet = wordsByLength.get(length);

        if (!wordSet) {
            continue;
        }

        const candidate = typedStream.slice(-length);

        if (wordSet.has(candidate)) {
            foundWords.push(candidate);
        }
    }

    return foundWords;
}

function spawnFloatingMessage(message, extraClass = '') {
    if (!floatingRewardsLayer) {
        return;
    }

    const reward = document.createElement('span');
    reward.className = `float-reward ${extraClass}`.trim();
    reward.textContent = message;
    reward.style.left = `${18 + Math.random() * 60}%`;
    reward.style.bottom = `${50 + Math.random() * 26}px`;
    floatingRewardsLayer.appendChild(reward);

    setTimeout(() => {
        reward.remove();
    }, 1250);
}

function spawnFloatingReward(points, word) {
    spawnFloatingMessage(`+${points} 🍌 ${getDisplayWord(word).toUpperCase()}`);
}

function spawnMonkeyHireMessage(monkeyType) {
    const prefix = monkeyType.rarity === 'super-rare' ? 'SUPER RARE' : 'HIRED';
    const star = monkeyType.rarity === 'super-rare' ? ' ★' : '';
    spawnFloatingMessage(`${prefix}: ${monkeyType.name.toUpperCase()}${star}`, monkeyType.rarity === 'super-rare' ? 'is-super-rare' : 'is-hire');
}

function awardWords(words) {
    words.forEach((word) => {
        const points = calculateWordPoints(word);
        bananas += points;
        wordsTyped += 1;
        recentWords.unshift({ word, points });
        appendWordReward(word, points);
        spawnFloatingReward(points, word);
    });

    recentWords = recentWords.slice(0, recentWordLimit);
}

function animateMonkey(monkeyIndex, letter) {
    if (monkeysOwned <= 0) {
        return;
    }

    let targetIndex = typeof monkeyIndex === 'number' ? monkeyIndex : Math.floor(Math.random() * monkeysOwned);

    if (targetIndex < 0 || targetIndex >= monkeysOwned) {
        targetIndex = Math.floor(Math.random() * monkeysOwned);
    }

    const monkeyEl = monkeyOfficeGrid.querySelector(`[data-monkey-slot="${targetIndex}"]`);
    if (!monkeyEl) {
        return;
    }

    const bubble = monkeyEl.querySelector('.letter-bubble');
    if (bubble) {
        bubble.textContent = String(letter).toUpperCase();
    }

    monkeyEl.classList.remove('typing');
    void monkeyEl.offsetWidth;
    monkeyEl.classList.add('typing');

    if (monkeyAnimationTimeouts.has(targetIndex)) {
        clearTimeout(monkeyAnimationTimeouts.get(targetIndex));
    }

    const timeoutId = setTimeout(() => {
        monkeyEl.classList.remove('typing');
        if (bubble) {
            bubble.textContent = '';
        }
        monkeyAnimationTimeouts.delete(targetIndex);
    }, monkeyAnimationDurationMs);

    monkeyAnimationTimeouts.set(targetIndex, timeoutId);
}

function typeRandomLetter(source = 'player', monkeyIndex = null) {
    const randomLetter = alphabet[Math.floor(Math.random() * alphabet.length)];

    typedStream += randomLetter;
    if (typedStream.length > maxSavedStreamLength) {
        typedStream = typedStream.slice(-maxSavedStreamLength);
    }

    lettersTyped += 1;
    appendOutputLetter(randomLetter, source);
    animateMonkey(monkeyIndex, randomLetter);

    const foundWords = findNewWordsAtEnd();
    if (foundWords.length > 0) {
        awardWords(foundWords);
    }

    updateDisplay();
    saveGame();
}

function buyMonkey() {
    if (bananas < monkeyCost) {
        return;
    }

    bananas -= monkeyCost;
    monkeysOwned += 1;

    const hiredTypeId = getRandomMonkeyTypeId();
    monkeyRoster.push(hiredTypeId);
    const hiredMonkeyType = getMonkeyType(hiredTypeId);

    monkeyCost = Math.ceil(monkeyCost * 1.55);

    updateDisplay();
    saveGame();
    spawnMonkeyHireMessage(hiredMonkeyType);

    requestAnimationFrame(() => {
        animateMonkey(monkeysOwned - 1, hiredMonkeyType.rarity === 'super-rare' ? '★' : '!');
    });
}

function clearPendingMonkeyTyping() {
    pendingMonkeyTypeTimeouts.forEach((timeoutId) => clearTimeout(timeoutId));
    pendingMonkeyTypeTimeouts = [];
}

function runMonkeyTyping() {
    if (monkeysOwned <= 0) {
        return;
    }

    clearPendingMonkeyTyping();

    monkeyRoster.forEach((typeId, index) => {
        const monkeyType = getMonkeyType(typeId);
        const typeMultiplier = Math.max(1, Number(monkeyType.speedMultiplier) || 1);
        const totalMultiplier = typeMultiplier * getGlobalSpeedMultiplier();
        let lettersThisCycle = Math.floor(totalMultiplier);
        const fractionalChance = totalMultiplier - lettersThisCycle;

        if (Math.random() < fractionalChance) {
            lettersThisCycle += 1;
        }

        lettersThisCycle = clamp(lettersThisCycle, 1, 20);

        for (let burst = 0; burst < lettersThisCycle; burst += 1) {
            const delay = Math.floor((monkeyTypingIntervalMs / lettersThisCycle) * burst + Math.random() * 80);
            const timeoutId = setTimeout(() => {
                typeRandomLetter('monkey', index);
            }, delay);

            pendingMonkeyTypeTimeouts.push(timeoutId);
        }
    });
}

function renderMonkeyOffice() {
    ensureMonkeyRosterMatchesCount();

    if (monkeysOwned === 0) {
        monkeyOfficeSummary.textContent = 'No monkeys hired yet.';
        monkeyOfficeGrid.innerHTML = `
            <div class="office-empty-state">
                <span class="office-empty-emoji" aria-hidden="true">🐒</span>
                <p>Hire your first monkey to fill the office.</p>
            </div>
        `;
        return;
    }

    monkeyOfficeSummary.textContent = `${formatNumber(monkeysOwned)} monkey${monkeysOwned === 1 ? '' : 's'} in the office`;
    monkeyOfficeGrid.innerHTML = monkeyRoster
        .map((typeId, index) => {
            const monkeyType = getMonkeyType(typeId);
            const rarityClass = monkeyType.rarity === 'super-rare' ? ' is-super-rare' : '';
            const rarityLabel = getMonkeyRarityLabel(monkeyType);
            const rarityBadge = monkeyType.rarity === 'super-rare'
                ? '<span class="monkey-rarity-star" aria-hidden="true">★</span>'
                : '';

            return `
                <div class="office-monkey${rarityClass}" data-monkey-slot="${index}" title="${monkeyType.name} — ${rarityLabel}${monkeyType.rarity === 'super-rare' ? ' • 5x speed' : ''}" aria-label="${monkeyType.name}, ${rarityLabel}${monkeyType.rarity === 'super-rare' ? ', five times speed' : ''}">
                    <span class="letter-bubble" aria-hidden="true"></span>
                    ${rarityBadge}
                    <div class="office-monkey-art">
                        <img src="${getMonkeySpriteSrc(monkeyType)}" alt="" class="monkey-sprite" loading="lazy" />
                    </div>
                </div>
            `;
        })
        .join('');
}

function getMilestoneProgress(milestone) {
    switch (milestone.metric) {
        case 'letters':
            return lettersTyped;
        case 'words':
            return wordsTyped;
        case 'monkeys':
            return monkeysOwned;
        case 'superRares':
            return getTotalSuperRaresOwned();
        case 'officeLevel':
            return officeLevel;
        default:
            return 0;
    }
}

function buyUpgrade(upgradeId) {
    const upgrade = UPGRADE_DEFS[upgradeId];
    if (!upgrade) {
        return;
    }

    const currentLevel = getUpgradeLevel(upgradeId);
    if (currentLevel >= upgrade.maxLevel) {
        return;
    }

    const cost = getUpgradeCost(upgradeId);
    if (bananas < cost) {
        return;
    }

    bananas -= cost;
    upgrades[upgradeId] = currentLevel + 1;
    spawnFloatingMessage(`${upgrade.name.toUpperCase()} +1`, 'is-hire');
    updateDisplay();
    saveGame();
}

function unlockNextOffice() {
    const nextOffice = getNextOffice();
    if (!nextOffice) {
        spawnFloatingMessage('ALL OFFICES UNLOCKED', 'is-hire');
        return;
    }

    if (bananas < nextOffice.unlockCost) {
        const needed = nextOffice.unlockCost - bananas;
        spawnFloatingMessage(`NEED ${formatNumber(needed)} MORE 🍌`, 'is-hire');
        updateProgressionPanel();
        return;
    }

    bananas -= nextOffice.unlockCost;
    officeLevel = clamp(officeLevel + 1, 1, OFFICE_BUILDINGS.length);
    spawnFloatingMessage(`${nextOffice.name.toUpperCase()} UNLOCKED`, 'is-super-rare');
    updateDisplay();
    saveGame();
}

function claimMilestone(milestoneId) {
    const milestone = MILESTONES.find((entry) => entry.id === milestoneId);
    if (!milestone || claimedMilestones.includes(milestoneId)) {
        return;
    }

    if (getMilestoneProgress(milestone) < milestone.target) {
        return;
    }

    claimedMilestones.push(milestoneId);
    bananas += milestone.reward;
    spawnFloatingMessage(`GOAL +${formatNumber(milestone.reward)} 🍌`, 'is-hire');
    updateDisplay();
    saveGame();
}

function renderUpgradeCard(upgradeId) {
    const upgrade = UPGRADE_DEFS[upgradeId];
    const level = getUpgradeLevel(upgradeId);
    const isMaxed = level >= upgrade.maxLevel;
    const cost = isMaxed ? 0 : getUpgradeCost(upgradeId);
    const canAfford = !isMaxed && bananas >= cost;

    return `
        <article class="progress-card">
            <div class="progress-card-copy">
                <span class="progress-branch">${upgrade.branch}</span>
                <h3>${upgrade.name}</h3>
                <p>${upgrade.description}</p>
                <span class="progress-meta">Level ${level} / ${upgrade.maxLevel}</span>
            </div>
            <button class="progress-buy-button" data-upgrade-id="${upgrade.id}" ${(!canAfford || isMaxed) ? 'disabled' : ''}>
                ${isMaxed ? 'Maxed' : `${formatNumber(cost)} 🍌`}
            </button>
        </article>
    `;
}

function getOfficeBonusSummary(office) {
    const parts = [];

    if (office.speedBonus > 0) {
        parts.push(`+${Math.round(office.speedBonus * 100)}% speed`);
    }

    if (office.wordBonus > 0) {
        parts.push(`+${office.wordBonus} word bonus`);
    }

    if (office.incomeMultiplier > 1) {
        parts.push(`${office.incomeMultiplier.toFixed(2)}x income`);
    }

    if (office.rareBonus > 0) {
        parts.push(`+${Math.round(office.rareBonus * 100)}% rare odds`);
    }

    return parts.length > 0 ? parts.join(' • ') : 'No bonus yet';
}

function updateProgressionPanel() {
    if (!officeUpgradeList || !skillsUpgradeList || !milestonesList) {
        return;
    }

    const currentOffice = getCurrentOffice();
    const nextOffice = getNextOffice();

    currentOfficeNameEl.textContent = `${currentOffice.name} — Floor ${currentOffice.floor}`;
    currentOfficeBonusEl.textContent = `${getOfficeBonusSummary(currentOffice)} • Rare odds ${Math.round(getSuperRareChance() * 100)}%`;

    officeUpgradeList.innerHTML = `
        <article class="progress-card office-progress-card">
            <div class="progress-card-copy">
                <span class="progress-branch">Office</span>
                <h3>${nextOffice ? nextOffice.name : 'All Offices Unlocked'}</h3>
                <p>${nextOffice ? nextOffice.description : 'You have reached the top of the monkey business ladder.'}</p>
                <span class="progress-meta">${nextOffice ? getOfficeBonusSummary(nextOffice) : getOfficeBonusSummary(currentOffice)}</span>
            </div>
            <button class="progress-buy-button" data-office-unlock="true" ${(!nextOffice || bananas < nextOffice.unlockCost) ? 'disabled' : ''}>
                ${nextOffice ? `${formatNumber(nextOffice.unlockCost)} 🍌` : 'Maxed'}
            </button>
        </article>
    `;

    skillsUpgradeList.innerHTML = Object.keys(UPGRADE_DEFS).map(renderUpgradeCard).join('');

    milestonesList.innerHTML = MILESTONES.map((milestone) => {
        const progress = getMilestoneProgress(milestone);
        const ratio = clamp(progress / milestone.target, 0, 1);
        const isClaimed = claimedMilestones.includes(milestone.id);
        const isReady = progress >= milestone.target && !isClaimed;

        return `
            <article class="milestone-card ${isClaimed ? 'is-claimed' : ''}">
                <div class="milestone-copy">
                    <h3>${milestone.name}</h3>
                    <p>${milestone.description}</p>
                    <div class="milestone-bar" aria-hidden="true">
                        <span style="width: ${Math.round(ratio * 100)}%"></span>
                    </div>
                    <small>${formatNumber(Math.min(progress, milestone.target))} / ${formatNumber(milestone.target)} • Reward ${formatNumber(milestone.reward)} 🍌</small>
                </div>
                <button class="progress-buy-button milestone-claim-button" data-milestone-id="${milestone.id}" ${!isReady ? 'disabled' : ''}>
                    ${isClaimed ? 'Claimed' : 'Claim'}
                </button>
            </article>
        `;
    }).join('');

    bindProgressionButtons();
}

function canAffordOfficeUnlock() {
    const nextOffice = getNextOffice();
    return Boolean(nextOffice && bananas >= nextOffice.unlockCost);
}

function bindProgressionButtons() {
    const officeButton = officeUpgradeList.querySelector('[data-office-unlock]');
    if (officeButton && !officeButton.dataset.bound) {
        officeButton.dataset.bound = 'true';
        bindFastTap(officeButton, unlockNextOffice);
    }

    skillsUpgradeList.querySelectorAll('[data-upgrade-id]').forEach((button) => {
        if (button.dataset.bound) {
            return;
        }

        button.dataset.bound = 'true';
        bindFastTap(button, () => buyUpgrade(button.dataset.upgradeId));
    });

    milestonesList.querySelectorAll('[data-milestone-id]').forEach((button) => {
        if (button.dataset.bound) {
            return;
        }

        button.dataset.bound = 'true';
        bindFastTap(button, () => claimMilestone(button.dataset.milestoneId));
    });
}

function openUpgradesPanel() {
    updateProgressionPanel();
    upgradePanel.classList.remove('is-hidden');
    upgradePanel.setAttribute('aria-hidden', 'false');
}

function closeUpgradesPanel() {
    upgradePanel.classList.add('is-hidden');
    upgradePanel.setAttribute('aria-hidden', 'true');
}

function saveGame() {
    const saveData = {
        bananas,
        lettersTyped,
        wordsTyped,
        monkeysOwned,
        monkeyCost,
        typedStream,
        recentWords,
        monkeyRoster,
        officeLevel,
        upgrades,
        claimedMilestones
    };

    localStorage.setItem(SAVE_KEY, JSON.stringify(saveData));
    LEGACY_SAVE_KEYS.forEach((key) => {
        if (key !== SAVE_KEY) {
            localStorage.removeItem(key);
        }
    });
}

function loadGame() {
    const availableKeys = [SAVE_KEY, ...LEGACY_SAVE_KEYS];
    let rawSave = null;

    for (const key of availableKeys) {
        rawSave = localStorage.getItem(key);
        if (rawSave) {
            break;
        }
    }

    if (!rawSave) {
        ensureProgressionState();
        return;
    }

    try {
        const saveData = JSON.parse(rawSave);

        bananas = Number(saveData.bananas) || 0;
        lettersTyped = Number(saveData.lettersTyped) || 0;
        wordsTyped = Number(saveData.wordsTyped) || 0;
        monkeysOwned = Number(saveData.monkeysOwned) || 0;
        monkeyCost = Number(saveData.monkeyCost) || 50;
        typedStream = typeof saveData.typedStream === 'string' ? saveData.typedStream.slice(-maxSavedStreamLength) : '';
        recentWords = Array.isArray(saveData.recentWords) ? saveData.recentWords.slice(0, recentWordLimit) : [];
        monkeyRoster = Array.isArray(saveData.monkeyRoster) ? saveData.monkeyRoster.map(normalizeRosterEntry) : [];
        officeLevel = Number(saveData.officeLevel) || 1;
        upgrades = { ...upgrades, ...(saveData.upgrades || {}) };
        claimedMilestones = Array.isArray(saveData.claimedMilestones) ? saveData.claimedMilestones : [];

        ensureProgressionState();
        ensureMonkeyRosterMatchesCount();
    } catch (error) {
        console.warn('Could not load saved Monkey Business game.', error);
        availableKeys.forEach((key) => localStorage.removeItem(key));
        ensureProgressionState();
    }
}

function resetGame() {
    const shouldReset = window.confirm('Reset Monkey Business and clear your saved bananas, words, monkeys, offices, upgrades, and goals?');

    if (!shouldReset) {
        return;
    }

    bananas = 0;
    lettersTyped = 0;
    wordsTyped = 0;
    monkeysOwned = 0;
    monkeyCost = 50;
    typedStream = '';
    recentWords = [];
    monkeyRoster = [];
    officeLevel = 1;
    upgrades = {
        fasterTypewriters: 0,
        betterDictionary: 0,
        bananaPayroll: 0,
        rareRecruiter: 0
    };
    claimedMilestones = [];

    monkeyAnimationTimeouts.forEach((timeoutId) => clearTimeout(timeoutId));
    monkeyAnimationTimeouts.clear();
    clearPendingMonkeyTyping();

    [SAVE_KEY, ...LEGACY_SAVE_KEYS].forEach((key) => localStorage.removeItem(key));
    outputArea.innerHTML = '<span class="placeholder">Tap TYPE to begin...</span>';
    if (floatingRewardsLayer) {
        floatingRewardsLayer.innerHTML = '';
    }
    updateDisplay();
}

function bindFastTap(button, handler) {
    let handledByPointer = false;

    button.addEventListener('pointerdown', (event) => {
        if (event.pointerType === 'mouse' && event.button !== 0) {
            return;
        }

        handledByPointer = true;
        event.preventDefault();
        handler();
    });

    button.addEventListener('click', (event) => {
        if (handledByPointer) {
            handledByPointer = false;
            event.preventDefault();
            return;
        }

        handler();
    });
}

bindFastTap(typeButton, () => typeRandomLetter('player'));
bindFastTap(buyMonkeyButton, buyMonkey);
resetButton.addEventListener('click', resetGame);
upgradesButton.addEventListener('click', openUpgradesPanel);
closeUpgradesButton.addEventListener('click', closeUpgradesPanel);
upgradePanel.addEventListener('click', (event) => {
    if (event.target === upgradePanel) {
        closeUpgradesPanel();
    }
});

document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && !upgradePanel.classList.contains('is-hidden')) {
        closeUpgradesPanel();
    }
});

loadGame();
syncOfficeVisuals(true);
updateDisplay();
setInterval(runMonkeyTyping, monkeyTypingIntervalMs);
